function cap(s){ return s.charAt(0).toUpperCase()+s.slice(1); }
function blend(a,b){
  a=String(a||'').trim().toLowerCase(); b=String(b||'').trim().toLowerCase();
  if(!a||!b) return [];
  var out=[];
  for(var i=1;i<a.length;i++){ for(var j=1;j<b.length;j++){ out.push(cap(a.slice(0,i)+b.slice(j))); } }
  for(var i2=1;i2<a.length;i2++){ for(var j2=1;j2<b.length;j2++){ out.push(cap(b.slice(0,j2)+a.slice(i2))); } }
  var seen={}, uniq=[]; out.forEach(function(s){ if(!seen[s]){seen[s]=1; uniq.push(s);} });
  return uniq;
}
function shipName(a,b,rng){
  rng=rng||Math.random;
  var arr=blend(a,b);
  if(!arr.length) return {error:'请输入两个名字'};
  for(var i=arr.length-1;i>0;i--){ var k=Math.floor(rng()*(i+1)); var t=arr[i]; arr[i]=arr[k]; arr[k]=t; }
  return {names:arr, pick:arr[0]};
}
var EXPORTS={blend:blend, shipName:shipName};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.ShipNameForgePure = EXPORTS; }
